using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class FacadePack : IFacadePack
    {
        public (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(Surface surface, int uCount, int vCount)
        {
            if (surface == null) throw new ArgumentException("Surface is missing.");
            if (uCount < 1 || vCount < 1) throw new ArgumentException("U Count and V Count must be at least 1.");

            var du = surface.Domain(0);
            var dv = surface.Domain(1);
            var pts = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
                for (int j = 0; j <= vCount; j++)
                    pts[i, j] = surface.PointAt(du.ParameterAt((double)i / uCount), dv.ParameterAt((double)j / vCount));

            var panels = new List<Panel>();
            var outlines = new List<Curve>();
            for (int i = 0; i < uCount; i++)
                for (int j = 0; j < vCount; j++)
                {
                    var p = new Panel(pts[i, j], pts[i + 1, j], pts[i + 1, j + 1], pts[i, j + 1], i * vCount + j);
                    panels.Add(p);
                    outlines.Add(p.Outline);
                }
            return (panels, outlines);
        }

        public (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(Panel panel)
        {
            if (panel == null) throw new ArgumentException("Panel is missing.");
            return (panel.Corners.ToList(), panel.Outline, panel.Area, panel.Center, panel.Index);
        }

        public (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            List<Panel> panels, double tolerance, IBettaReport report)
        {
            panels = panels ?? new List<Panel>();
            var dev = panels.Select(p => p.Deviation).ToList();
            var flat = dev.Select(d => d <= tolerance).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = panels.Count - flatCount;
            if (notFlat * 2 > panels.Count)
                report.Warning($"{notFlat} of {panels.Count} panels are not flat.");
            return (dev, flat, flatCount);
        }

        public (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            List<Panel> panels, double tolerance)
        {
            var types = (panels ?? new List<Panel>()).Select(p =>
                p.Deviation <= tolerance ? "flat" :
                p.Deviation <= 10 * tolerance ? "cold-bent" : "custom").ToList();
            return (types, types.Count(t => t == "flat"), types.Count(t => t == "cold-bent"), types.Count(t => t == "custom"));
        }

        public (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(List<Panel> panels)
        {
            if (panels == null || panels.Count == 0) throw new ArgumentException("There are no panels.");
            var areas = panels.Select(p => p.Area).ToList();
            return (areas.Sum(), areas.Min(), areas.Max(), areas.Average());
        }

        private static double[] Signature(Panel p)
        {
            var edges = Enumerable.Range(0, 4).Select(p.Edge).OrderBy(x => x);
            var diags = new[] { p.Corners[0].DistanceTo(p.Corners[2]), p.Corners[1].DistanceTo(p.Corners[3]) }.OrderBy(x => x);
            return edges.Concat(diags).ToArray();
        }

        public (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            List<Panel> panels, double tolerance)
        {
            var group = new List<int>();
            var reps = new List<Panel>();
            var repSigs = new List<double[]>();
            foreach (var p in panels ?? new List<Panel>())
            {
                var sig = Signature(p);
                int g = -1;
                for (int k = 0; k < repSigs.Count && g < 0; k++)
                {
                    bool same = true;
                    for (int m = 0; m < 6 && same; m++)
                        if (m < 4 ? Math.Abs(sig[m] - repSigs[k][m]) > tolerance : Math.Abs(sig[m] - repSigs[k][m]) > tolerance)
                            same = false;
                    if (same) g = k;
                }
                if (g < 0)
                {
                    g = reps.Count;
                    reps.Add(p);
                    repSigs.Add(sig);
                }
                group.Add(g);
            }
            return (group, reps.Count, reps);
        }

        public Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            List<Panel> panels, double sheetWidth, double sheetHeight, double spacing,
            CancellationToken cancellationToken, IProgress<int> progress, IBettaReport report)
        {
            var parts = (panels ?? new List<Panel>()).Select(p => (w: p.Width, h: p.Height)).ToList();
            var result = Task.Run(() => Nest(parts, sheetWidth, sheetHeight, spacing, cancellationToken, progress), cancellationToken);
            return result.ContinueWith(t =>
            {
                var r = t.GetAwaiter().GetResult();
                if (r.unplaced > 0)
                    report.Warning($"{r.unplaced} panels fit on no sheet.");
                return r.value;
            }, cancellationToken);
        }

        private static (
            (List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization) value, int unplaced)
            Nest(List<(double w, double h)> parts, double W, double H, double s, CancellationToken ct, IProgress<int> progress)
        {
            var order = Enumerable.Range(0, parts.Count).OrderByDescending(i => parts[i].h).ToList();
            var outlines = new List<Curve>();
            var sheets = new List<int>();
            double placedArea = 0;
            int unplaced = 0;

            int sheet = -1;
            double shelfX = 0, shelfY = 0, shelfH = 0;
            bool shelfOpen = false;

            void Place(double w, double h)
            {
                double x0 = sheet * (W + 100) + shelfX, y0 = shelfY;
                var rect = new Rectangle3d(Plane.WorldXY, new Point3d(x0, y0, 0), new Point3d(x0 + w, y0 + h, 0));
                outlines.Add(rect.ToNurbsCurve());
                sheets.Add(sheet);
                placedArea += w * h;
                shelfX += w + s;
            }

            for (int n = 0; n < order.Count; n++)
            {
                ct.ThrowIfCancellationRequested();
                var (w, h) = parts[order[n]];
                double maxW = W - 2 * s, maxH = H - 2 * s;
                bool fitsNormal = w <= maxW && h <= maxH;
                bool fitsTurned = h <= maxW && w <= maxH;

                if (!fitsNormal && !fitsTurned)
                {
                    unplaced++;
                }
                else
                {
                    bool placed = false;
                    // current shelf
                    if (shelfOpen)
                    {
                        if (shelfX + w <= W - s && h <= shelfH) { Place(w, h); placed = true; }
                        else if (shelfX + h <= W - s && w <= shelfH) { Place(h, w); placed = true; }
                    }
                    // new shelf on current sheet
                    if (!placed && shelfOpen)
                    {
                        double ny = shelfY + shelfH + s;
                        if (fitsNormal && ny + h <= H - s) { StartShelf(ny, h); Place(w, h); placed = true; }
                        else if (fitsTurned && ny + w <= H - s) { StartShelf(ny, w); Place(h, w); placed = true; }
                    }
                    // new sheet
                    if (!placed)
                    {
                        sheet++;
                        if (fitsNormal) { StartShelf(s, h); Place(w, h); }
                        else { StartShelf(s, w); Place(h, w); }
                    }
                }
                progress?.Report((int)(100.0 * (n + 1) / order.Count));
            }

            void StartShelf(double y, double height)
            {
                shelfOpen = true;
                shelfX = s;
                shelfY = y;
                shelfH = height;
            }

            int count = sheet + 1;
            double util = count == 0 ? 0 : placedArea / (count * W * H);
            return ((outlines, sheets, count, util), unplaced);
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder("Index,Width,Height,Area,Deviation\n");
            foreach (var p in panels ?? new List<Panel>())
                sb.Append(string.Join(",", p.Index.ToString(inv), p.Width.ToString("R", inv), p.Height.ToString("R", inv),
                    p.Area.ToString("R", inv), p.Deviation.ToString("R", inv))).Append('\n');
            var csv = sb.ToString();

            if (!write) return (csv, false);
            if (string.IsNullOrWhiteSpace(path)) throw new ArgumentException("Path is empty; cannot write the cut list.");
            File.WriteAllText(path, csv);
            return (csv, true);
        }
    }
}
